#[test]
fn unshare_copies_shared_table_and_solo_is_noop() {
    let mut pipes: PipeSpace<4, 8, 4> = PipeSpace::new();
    let id = pipes.create_pipe(1, 0, 1, false).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    // solo task: unshare must be a no-op (no extra retain, fds intact)
    pipes.unshare(1).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    assert!(pipes.lookup(1, 0).is_some());
    // share with task 2, then unshare task 1: private copy keeps both ends
    pipes.share(2, 1).unwrap();
    pipes.unshare(1).unwrap();
    assert!(pipes.lookup(1, 0).is_some());
    assert!(pipes.lookup(1, 1).is_some());
    assert_eq!(pipes.pipe_ends(id), 4);
    // task 2 still shares the original table; closing its ends frees only its refs
    pipes.close(2, 0).unwrap();
    pipes.close(2, 1).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    assert!(pipes.lookup(1, 0).is_some());
    // unknown task: Ok, nothing allocated
    pipes.unshare(99).unwrap();
    assert_eq!(pipes.task_fds(99), 0);
}

#[test]
fn remove_busy_only_for_active_children_not_inactive_slots() {
    let mut cg: CgroupFs<4> = CgroupFs::new();
    cg.create(b"/a.slice", 0).unwrap();
    cg.create(b"/a.slice/child", 0).unwrap();
    // active child blocks parent removal (Busy), even with zero members
    assert_eq!(cg.remove(b"/a.slice", 0), Err(ViewError::Busy));
    // leaf with no children and no members removes cleanly
    cg.remove(b"/a.slice/child", 0).unwrap();
    cg.remove(b"/a.slice", 0).unwrap();
    // freed slots are inactive: must not block re-creation or sibling removal
    cg.create(b"/b.slice", 0).unwrap();
    cg.create(b"/b.slice/kid", 0).unwrap();
    cg.remove(b"/b.slice/kid", 0).unwrap();
    cg.remove(b"/b.slice", 0).unwrap();
    // root is never removable; non-root uid denied
    assert_eq!(cg.remove(b"/", 0), Err(ViewError::PermissionDenied));
    cg.create(b"/c.slice", 0).unwrap();
    assert_eq!(cg.remove(b"/c.slice", 1000), Err(ViewError::PermissionDenied));
    cg.remove(b"/c.slice", 0).unwrap();
}

#[test]
fn override_arms_apply_values_and_reject_unknown() {
    let mut c = InstanceConfig::parse(VALID.as_bytes()).unwrap();
    // table: (key, value, expected-field-check)
    c.apply_override(b"instance.workdir", b"\"/work\"").unwrap();
    assert_eq!(c.workdir.as_bytes(), b"/work");
    c.apply_override(b"instance.environment", b"[\"A=1\"]").unwrap();
    assert_eq!(c.environment.as_slice().len(), 1);
    c.apply_override(b"contract.syscalls.control", b"\"selective\"").unwrap();
    assert_eq!(c.dispatch_mode, DispatchMode::Selective);
    c.apply_override(b"contract.catalog", b"3").unwrap();
    assert_eq!(c.contract_catalog_version, 3);
    // unknown keys fail closed; derived fields rejected
    assert!(c.apply_override(b"no.such.key", b"\"x\"").is_err());
    assert!(c.apply_override(b"contract.digest", b"\"x\"").is_err());
}
